insert into public.products(business_unit_id,code,name,description,product_type,status,is_system) select bu.id,'LANDER_SOLUTIONS','Lander Solutions','Atendimento institucional e de serviços da Lander Solutions.','other','active',true from public.business_units bu where bu.code='CORPORATIVO' and not exists(select 1 from public.products where code='LANDER_SOLUTIONS');
insert into public.support_product_settings(legal_entity_id,product_id,brand_name,internal_description,timezone,default_language,status) select bu.legal_entity_id,p.id,p.name,p.description,'America/Sao_Paulo','pt-BR','active' from public.products p join public.business_units bu on bu.id=p.business_unit_id where p.status='active' on conflict(product_id) do nothing;
insert into public.support_automation_flows(legal_entity_id,product_id,status) select legal_entity_id,product_id,'active' from public.support_product_settings on conflict(product_id) do nothing;
